IFNULL(
(
SELECT  SUM(debit) FROM ${filter.tableName}
WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id)
AND date <= #{filter.dateTo}

    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


    AND other_id = #{filter.other}


    AND class_id = #{filter.classId}

) - (
SELECT SUM(credit)  FROM ${filter.tableName}
WHERE chart_account_id IN (SELECT id FROM chart_accounts WHERE chart_account_group_id = g.id)
AND date <= #{filter.dateTo}

    AND company_id = #{filter.companyId}


    AND customer_id = #{filter.organizationId}


    AND vendor_id = #{filter.vendorId}


    AND other_id = #{filter.other}


    AND class_id = #{filter.classId}

)
, 0) AS totalAmount

